import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import '../../core/theme/orenza_theme.dart';
import '../../core/widgets/system_states.dart';

class WalletSnapshot { final Map<String,dynamic> data; const WalletSnapshot(this.data); double n(String key,[String? fallback]){final v=data[key]??(fallback==null?null:data[fallback]);return v is num?v.toDouble():double.tryParse(v?.toString()??'')??0;} String s(String key,String fallback)=>data[key]?.toString()??fallback; bool get sandbox=>data['sandbox_mode']==true; List<Map<String,dynamic>> get movements{final v=data['movements'];return v is List?v.whereType<Map>().map((x)=>Map<String,dynamic>.from(x)).toList():const [];}}
class WalletScreen extends StatefulWidget{const WalletScreen({super.key});@override State<WalletScreen> createState()=>_WalletScreenState();}
class _WalletScreenState extends State<WalletScreen>{late Future<WalletSnapshot> future;@override void initState(){super.initState();future=_load();}Future<WalletSnapshot> _load()async{final c=Supabase.instance.client;if(c.auth.currentSession==null)throw StateError('Authentication required.');try{final r=await c.rpc('get_wallet_snapshot');if(r is Map)return WalletSnapshot(Map<String,dynamic>.from(r));if(r is List&&r.isNotEmpty&&r.first is Map)return WalletSnapshot(Map<String,dynamic>.from(r.first));}catch(_){ }final r=await c.rpc('get_broker_dashboard');if(r is Map)return WalletSnapshot(Map<String,dynamic>.from(r));if(r is List&&r.isNotEmpty&&r.first is Map)return WalletSnapshot(Map<String,dynamic>.from(r.first));throw StateError('Backend returned no wallet data.');}void retry()=>setState(()=>future=_load());
@override Widget build(BuildContext context)=>FutureBuilder<WalletSnapshot>(future:future,builder:(c,s){if(s.connectionState==ConnectionState.waiting)return const AurenzaLoading(message:'Loading your wallet...');if(s.hasError)return AurenzaErrorState(message:s.error.toString(),onRetry:retry);final w=s.data!;final items=[('Available balance',w.n('available_balance','available'),Icons.account_balance_outlined),('Reserved balance',w.n('reserved_balance','reserved'),Icons.lock_outline),('Sandbox capital',w.n('sandbox_capital'),Icons.shield_outlined),('Trading balance',w.n('trading_balance','balance'),Icons.show_chart_outlined),('Profit',w.n('profit','pnl'),Icons.trending_up),('Withdrawable balance',w.n('withdrawable_balance'),Icons.payments_outlined)];return RefreshIndicator(onRefresh:()async{retry();},child:ListView(physics:const AlwaysScrollableScrollPhysics(),padding:const EdgeInsets.all(20),children:[Container(padding:const EdgeInsets.all(24),decoration:BoxDecoration(gradient:const LinearGradient(colors:[OrenzaColors.forest,OrenzaColors.forestGreen]),borderRadius:BorderRadius.circular(22)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('WALLET',style:TextStyle(color:Colors.white70,fontSize:11,fontWeight:FontWeight.w800,letterSpacing:1.5)),const SizedBox(height:8),Text('${w.s('currency','USD')} ${w.n('total_balance','portfolio_value').toStringAsFixed(2)}',style:const TextStyle(color:Colors.white,fontSize:30,fontWeight:FontWeight.w900)),const SizedBox(height:6),Text(w.sandbox?'SANDBOX MODE — backend controlled':'LIVE ACCOUNT',style:const TextStyle(color:OrenzaColors.softGold,fontSize:11,fontWeight:FontWeight.w700))])),const SizedBox(height:18),LayoutBuilder(builder:(c,x){final n=x.maxWidth>=900?3:2;final g=12.0,width=(x.maxWidth-g*(n-1))/n;return Wrap(spacing:g,runSpacing:g,children:[for(final i in items)SizedBox(width:width,child:Card(child:Padding(padding:const EdgeInsets.all(15),child:Row(children:[Icon(i.$3,color:OrenzaColors.gold),const SizedBox(width:10),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(i.$1,style:const TextStyle(color:OrenzaColors.slate,fontSize:11)),const SizedBox(height:4),Text('${w.s('currency','USD')} ${i.$2.toStringAsFixed(2)}',maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(fontWeight:FontWeight.w900))]))]))))]);}),const SizedBox(height:20),_section('Funding & payouts',[_row('Deposit status',w.s('deposit_status','Not available')), _row('Payout status',w.s('payout_status','Not available'))]),const SizedBox(height:20),_section('Balance movements',w.movements.isEmpty?[const Padding(padding:EdgeInsets.symmetric(vertical:18),child:Text('No balance movements returned by the backend yet.',style:TextStyle(color:OrenzaColors.slate)))]:[for(final m in w.movements)ListTile(contentPadding:EdgeInsets.zero,leading:Icon((m['amount'] is num&&(m['amount'] as num)>=0)?Icons.arrow_downward:Icons.arrow_upward,color:OrenzaColors.gold),title:Text(m['description']?.toString()??m['type']?.toString()??'Balance movement'),subtitle:Text(m['status']?.toString()??'recorded'),trailing:Text(m['amount']?.toString()??'0',style:const TextStyle(fontWeight:FontWeight.w900)))])]);});
Widget _section(String title,List<Widget> children)=>Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontSize:16,fontWeight:FontWeight.w900)),const SizedBox(height:8),...children])));Widget _row(String a,String b)=>ListTile(contentPadding:EdgeInsets.zero,title:Text(a),trailing:Text(b.toUpperCase(),style:const TextStyle(color:OrenzaColors.gold,fontSize:10,fontWeight:FontWeight.w800)));}
